import { useContext, useState } from 'react';
import AuthContext from '../context/AuthContext';

function Signup() {
  const { register } = useContext(AuthContext);
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [role, setRole] = useState('user');
  const [error, setError] = useState(null);

  const submit = async (e) => {
    e.preventDefault();
    try {
      await register(name, email, password, role);
      window.location.href = '/';
    } catch (err) {
      console.error('Signup error', err);
      const msg = err?.response?.data?.error || err?.message || 'Signup failed';
      setError(msg);
    }
  };

  return (
    <div className="page mt-10">
      <div className="container flex justify-center">
        <div className="card max-w-md w-full">
          <h2 className="text-2xl mb-6">Create Account</h2>
          <form onSubmit={submit}>
            <div className="form-group">
              <label className="form-label">Full Name</label>
              <input
                type="text"
                className="form-input"
                placeholder="John Doe"
                value={name}
                onChange={(e) => setName(e.target.value)}
                required
              />
            </div>

            <div className="form-group">
              <label className="form-label">Email Address</label>
              <input
                type="email"
                className="form-input"
                placeholder="name@company.com"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                required
              />
            </div>

            <div className="form-group">
              <label className="form-label">Password</label>
              <input
                type="password"
                className="form-input"
                placeholder="Choose a strong password"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                required
              />
            </div>

            <div className="form-group">
              <label className="form-label">I am a:</label>
              <select className="form-input" value={role} onChange={(e) => setRole(e.target.value)}>
                <option value="user">Candidate (Job Seeker)</option>
                <option value="recruiter">Recruiter (Post Jobs)</option>
              </select>
            </div>

            {error && <div className="alert alert-danger mb-4">{error}</div>}

            <button type="submit" className="btn btn-primary w-full">
              Get Started
            </button>

            <p className="muted text-sm text-center mt-6">
              Already have an account? <a href="/login" className="brand-link" style={{ color: 'var(--primary)', display: 'inline' }}>Sign In</a>
            </p>
          </form>
        </div>
      </div>
    </div>
  );
}

export default Signup;
